        ['Welcher Atomunfall traf Japan 2011 nach einem Tsunami?', 'Fukushima', [['Tschernobyl', 'Das war 1986, in der Ukraine. ☢️'], ['Bhopal', 'Das war eine Chemiefabrik in Indien, 1984. 🏭'], ['Hiroshima', 'Das war ein Bombenangriff von 1945, kein Unfall. 📅']], 'Ein Naturereignis kann einen technologischen Unfall auslösen.'],
        ['Wie heißen in Europa die gefährlichsten Fabriken, für die strenge Regeln gelten?', 'Seveso-Betriebe', [['Natura-2000-Gebiete', 'Das sind geschützte Naturräume. 🌿'], ['Fußgängerzonen', 'Das sind Straßen ohne Autos. 🚶'], ['Nationalparks', 'Sie schützen Natur. 🏞️']], 'Frankreich zählt mehr als 1 000 Seveso-Betriebe.'],
        ['Woher kommt der Name „Seveso“?', 'von einer italienischen Stadt, a 1976 von einer Giftwolke getroffen wurde', [['von einem Gelehrten, der Chemie erfand', 'Es ist ein Ortsname. 🧪'], ['von einem Fluss in Deutschland', 'Es liegt in Italien. 🇮🇹'], ['von einer Waschmittelmarke', 'Ganz und gar nicht. 🧺']], 'Nach diesem Unfall beschloss Europa gemeinsame Regeln (Seveso-Richtlinien).'],
        ['In welcher Stadt geriet die Chemiefabrik Lubrizol im September 2019 in Brand?', 'Rouen', [['Marseille', 'Nicht dort. 🌊'], ['Lille', 'Nicht dort. 🧭'], ['Straßburg', 'Nicht dort. 🗺️']], 'Eine riesige schwarze Rauchwolke zog über die Stadt.'],
        ['Was muss man tun, wenn die Warnsirene ertönt?', 'in einem Gebäude Schutz suchen, Türen und Fenster schließen und den Anweisungen folgen', [['hinausgehen und schauen, was los ist', 'Draußen ist man stärker gefährdet. 🚪'], ['die Geschwister von der Schule abholen', 'Auch ohne dich bringt eine Schule ihre Kinder in Sicherheit. 🏫'], ['alle anrufen', 'Leitungen bleiben frei für Rettungsdienste. 📵']], 'Man hört Radio oder folgt den offiziellen Meldungen.'],
        ['Was wird in Frankreich am ersten Mittwoch jedes Monats um zwölf Uhr getestet?', 'die Warnsirenen', [['Ampeln', 'Sie funktionieren jeden Tag. 🚦'], ['Kirchenglocken', 'Sie dienen nicht zur Warnung. 🔔'], ['Autoalarmanlagen', 'Das ist kein landesweiter Test. 🚗']], 'Das Testsignal dauert eine Minute und einundvierzig Sekunden.'],
        ['Wozu dient ein Plan zur Vorbeugung technologischer Risiken (PPRT)?', 'um Bebauung rund um gefährliche Fabriken zu begrenzen', [['um mehr Fabriken zu bauen', 'Er soll Gefahr verringern. 🏭'], ['um Urlaube zu planen', 'Damit hat er nichts zu tun. 🏖️'], ['um alle Fabriken Frankreichs zu schließen', 'Er regelt, er schließt nicht alles. 🔒']], 'Weniger Anwohner nahe der Gefahr bedeutet weniger Verwundbarkeit.'],
        ['Warum ist das Risiko größer, wenn eine gefährliche Fabrik nahe einer Stadt liegt?', 'weil viele Menschen und Güter gefährdet sind', [['weil Städte Explosionen anziehen', 'Städte ziehen keine Unfälle an. 🧲'], ['weil die Luft dort wärmer ist', 'Das ist nicht der Grund. 🌡️'], ['weil die Fabriken dort kleiner sind', 'Größe ist nicht das Problem. 📏']], 'Risiko = Gefahr × Betroffenheit: Je mehr betroffen ist, desto größer das Risiko.'],
        ['Welches Warnsystem ergänzt in Frankreich seit 2022 die Sirenen?', 'FR-Alert, eine Nachricht an Mobiltelefone', [['eine Brieftaube', 'Etwas langsam für eine Warnung. 🐦'], ['ein Plakat im Rathaus', 'Zu langsam für einen Notfall. 📄'], ['ein Feuerwerk', 'Das würde man völlig missverstehen. 🎆']], 'Die Nachricht erreicht alle Telefone im betroffenen Gebiet.'],
        ['Was ist ein technologisches Risiko?', 'ein Risiko durch menschliche Tätigkeiten: Fabriken, Kraftwerke, Staudämme, Gefahrguttransporte', [['ein Risiko durch einen Vulkan', 'Das ist ein Naturrisiko. 🌋'], ['das Risiko, sein Handy zu zerbrechen', 'Hier geht es um Gefahr für eine ganze Bevölkerung. 📱'], ['ein Risiko nur durch das Wetter', 'Wetter ist eine natürliche Gefahr. ⛈️']], 'Es entsteht durch unsere Technik, nicht durch die Natur.'],
        ['Warum ist der Transport gefährlicher Güter ein Risiko?', 'ein Lkw- oder Zugunfall kann ein Leck, einen Brand oder eine Explosion verursachen', [['weil Lkw zu langsam fahren', 'Langsamkeit ist nicht das Problem. 🐢'], ['weil sich Produkte von selbst verflüchtigen', 'Gefahr entsteht durch einen Unfall. 💨'], ['weil es verboten ist', 'Es ist erlaubt, aber streng geregelt. 📋']], 'Die betroffenen Lkw tragen eine orange Tafel mit Gefahrnummern.'],
        ['Welches Land erzeugt den größten Teil seines Stroms mit Kernkraft?', 'Frankreich', [['Deutschland', 'Es hat 2023 seine letzten Kraftwerke abgeschaltet. 🔌'], ['Italien', 'Es hat keine laufenden Kraftwerke mehr. 🇮🇹'], ['Dänemark', 'Es erzeugt vor allem Windstrom. 🌬️']], 'Kernkraft liefert etwa zwei Drittel des französischen Stroms.'],
        ['Wozu dient die Schutzübung in der Schule?', 'um zu wissen, was bei einem Unfall oder einer nahen Gefahr zu tun ist', [['zum Proben der Abschlussfeier', 'Mit Bühne hat das nichts zu tun. 🎭'], ['zum Testen der Kantine', 'Das ist keine Mahlzeit. 🍽️'], ['um früher nach Hause zu gehen', 'Sie verkürzt keinen Schultag. ⏰']], 'Das ist der Sicherheitsplan der Schule (PPMS).'],
        ['Was zeigt ein Gefahrenpiktogramm auf einem chemischen Produkt an?', 'dass es giftig, entzündlich oder ätzend sein kann', [['dass es im Angebot ist', 'Das ist kein Preisschild. 🏷️'], ['dass es in Frankreich hergestellt wurde', 'Das ist keine Herkunftsangabe. 🇫🇷'], ['dass man es essen kann', 'Auf keinen Fall! 🚫']], 'Diese roten Rauten sind in der ganzen Europäischen Union gleich.'],
        ['Warum liegen viele gefährliche Fabriken nahe an Häfen oder Flüssen?', 'um Rohstoffe leicht zu erhalten und Produkte leicht zu versenden', [['damit Arbeiter baden können', 'Das ist nicht der Grund. 🏊'], ['weil Wasser Explosionen löscht', 'Wasser verhindert keine Unfälle. 💧'], ['zufällig', 'Ihr Standort wird gewählt. 🎯']], 'Hafenindustriegebiete wie Fos bei Marseille bündeln solche Fabriken.'],
        ['Was ist Risikokultur?', 'die Gefahren in der Nähe seines Zuhauses und die richtigen Verhaltensweisen kennen', [['vor allem Angst haben', 'Es geht ums Wissen, nicht um Angst. 😨'], ['Extremsport lieben', 'Damit hat das nichts zu tun. 🪂'], ['Anweisungen ignorieren', 'Das Gegenteil. 🚫']], 'Eine informierte Bevölkerung reagiert besser auf eine Warnung.'],
        ['Wer organisiert bei einem Industrieunfall Warnung und Rettung?', 'der Präfekt und der Bürgermeister, mit Feuerwehr und Rettungsdiensten', [['nur der Schulleiter', 'Er schützt seine Schüler, organisiert aber keine Rettung für eine ganze Stadt. 🏫'], ['Ladenbesitzer im Viertel', 'Das ist nicht ihre Aufgabe. 🛒'], ['niemand: jeder hilft sich selbst', 'Genau dafür gibt es Rettungspläne. 📋']], 'Der ORSEC-Plan organisiert die Rettung auf Ebene des Departements.']
